			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_stage1__0_s:		; level1
p_level1_play:

			; Level1.cls 3: Dim i As Integer

			; Level1.cls 4: For i = 1 To 3
			dw kw_ltov, 1, var_level1_play_i
for1_t:

			; Level1.cls 5: Score.Add Maths.Square(i)
			dw p_maths_square_cl, var_level1_play_i
			dw p_score_add_c, var_maths_square_square

			; Level1.cls 6: Stars.Add
			dw p_stars_add_cl

			; Level1.cls 7: Next
			dw kw_next1l_n, var_level1_play_i, 3, for1_t
for1_e:

			; Level1.cls 8: Print "Level 1: score "; Score.Total(); ", stars here "; Stars.Count()
			dw p_score_total_c
			dw kw_printzoscii
			dw glyph_4C, glyph_65, glyph_76, glyph_65, glyph_6C, glyph_20, glyph_31, glyph_3A
			dw glyph_20, glyph_73, glyph_63, glyph_6F, glyph_72, glyph_65, glyph_20, 0		; "Level 1: score "
			dw kw_printint, var_score_total_total
			dw p_stars_count_cl
			dw kw_printzoscii
			dw glyph_2C, glyph_20, glyph_73, glyph_74, glyph_61, glyph_72, glyph_73, glyph_20
			dw glyph_68, glyph_65, glyph_72, glyph_65, glyph_20, 0		; ", stars here "
			dw kw_printint, var_stars_count_count
			dw kw_printnl
			dw p_level1_play_r
ovl_stage1__0_e:
ovl_stage1__1_s:		; maths
p_maths_square:

			; Maths.cls 3: Square = n * n
			dw kw_mulvv, var_maths_square_n, var_maths_square_n, var_maths_square_square
			dw p_maths_square_r
ovl_stage1__1_e:
ovl_stage1__2_s:		; stars
p_stars_add:

			; Stars.cls 4: n = n + 1
			dw kw_inc, var_stars_n
			dw p_stars_add_r
p_stars_count:

			; Stars.cls 7: Count = n
			dw kw_vtov, var_stars_n, var_stars_count_count
			dw p_stars_count_r
ovl_stage1__2_e:
; calls from this page into it (no page switch), GOTO / GOSUB of copies
ovl_stage1__x_s:
p_maths_square_cl:			ld hl, p_maths_square	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_maths_square_c
p_stars_add_cl:			ld hl, p_stars_add	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_stars_add_c
p_stars_count_cl:			ld hl, p_stars_count	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_stars_count_c
ovl_stage1__x_e:
			dw 0			; (never empty)
ovl_stage1_end:		; the end of its file; page variables (cleared on loading) follow
var_stars_n		equ ovl_stage1_end + 0		; 2 bytes (stars)
ovl_stage1_vsize	equ 2		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_stage1_end + ovl_stage1_vsize <= #8000, "page Stage1 (level1, maths, stars) is more than 16K (code and page variables)"
			DISPLAY "page Stage1 (PAGES.002):"
			DISPLAY "  level1 ", /D, ovl_stage1__0_e - ovl_stage1__0_s
			DISPLAY "  maths (home) ", /D, ovl_stage1__1_e - ovl_stage1__1_s
			DISPLAY "  stars (home) ", /D, ovl_stage1__2_e - ovl_stage1__2_s
